#include <vector>
#include <numeric>
#include <algorithm>

void bulk_insert(std::vector<int>& v, size_t count) {
    // 1. Pre-allocate to avoid O(N) reallocations
    v.reserve(v.size() + count);

    std::vector<int> temp(count);
    std::iota(temp.begin(), temp.end(), 1);

    // 2. Use range insertion (faster than 'count' push_backs)
    v.insert(v.end(), temp.begin(), temp.end());
}

// Insertion in middle is O(N)
void middle_insert(std::vector<int>& v) {
    v.insert(v.begin() + v.size() / 2, 999);
}
